    24→template <typename scalar_t, typename token_cnts_t>
    25→__global__ void moe_align_block_size_kernel(scalar_t* __restrict__ topk_ids,
    26→                                            int32_t* sorted_token_ids,
    27→                                            int32_t* expert_ids,
    28→                                            int32_t* total_tokens_post_pad,
    29→                                            int32_t num_experts,
    30→                                            int32_t block_size, size_t numel) {
    31→  const size_t tokens_per_thread = CEILDIV(numel, blockDim.x);
    32→  const size_t start_idx = threadIdx.x * tokens_per_thread;
    33→
    34→  extern __shared__ int32_t shared_mem[];
    35→  int32_t* cumsum = shared_mem;  // 1d tensor with shape (num_experts + 1)
    36→  token_cnts_t* tokens_cnts =
    37→      (token_cnts_t*)(shared_mem + num_experts +
    38→                      1);  // 2d tensor with shape (blockDim.x + 1, num_experts)
    39→
    40→  for (int i = 0; i < num_experts; ++i) {
    41→    tokens_cnts[index(num_experts, threadIdx.x + 1, i)] = 0;
    42→  }
    43→
    44→  /**
    45→   * In the first step we compute token_cnts[thread_index + 1][expert_index],
    46→   * which counts how many tokens in the token shard of thread_index are
    47→   * assigned to expert expert_index.
    48→   */
    49→  for (int i = start_idx; i < numel && i < start_idx + tokens_per_thread; ++i) {
    50→    ++tokens_cnts[index(num_experts, threadIdx.x + 1, topk_ids[i])];
    51→  }
    52→
    53→  __syncthreads();
    54→
    55→  // For each expert we accumulate the token counts from the different threads.
    56→  if (threadIdx.x < num_experts) {
    57→    tokens_cnts[index(num_experts, 0, threadIdx.x)] = 0;
    58→    for (int i = 1; i <= blockDim.x; ++i) {
    59→      tokens_cnts[index(num_experts, i, threadIdx.x)] +=
    60→          tokens_cnts[index(num_experts, i - 1, threadIdx.x)];
    61→    }
    62→  }
    63→
    64→  __syncthreads();
    65→
    66→  // We accumulate the token counts of all experts in thread 0.
    67→  if (threadIdx.x == 0) {
    68→    cumsum[0] = 0;
    69→    for (int i = 1; i <= num_experts; ++i) {
    70→      cumsum[i] = cumsum[i - 1] +
    71→                  CEILDIV(tokens_cnts[index(num_experts, blockDim.x, i - 1)],
    72→                          block_size) *
    73→                      block_size;
    74→    }
    75→    *total_tokens_post_pad = static_cast<int32_t>(cumsum[num_experts]);
    76→  }
    77→
    78→  __syncthreads();
    79→
    80→  /**
    81→   * For each expert, each thread processes the tokens of the corresponding
    82→   * blocks and stores the corresponding expert_id for each block.
    83→   */
    84→  if (threadIdx.x < num_experts) {
    85→    for (int i = cumsum[threadIdx.x]; i < cumsum[threadIdx.x + 1];
    86→         i += block_size) {
    87→      expert_ids[i / block_size] = threadIdx.x;
    88→    }
    89→  }
    90→
    91→  /**
    92→   * Each thread processes a token shard, calculating the index of each token
    93→   * after sorting by expert number. Given the example topk_ids =
    94→   * [0,1,2,1,2,3,0,3,4] and block_size = 4, then the output would be [0, 6, *,
    95→   * *, 1, 3, *, *, 2, 4, *, *, 5, 7, *, *, 8, *, *, *], where * represents a
    96→   * padding value(preset in python).
    97→   */
    98→  for (int i = start_idx; i < numel && i < start_idx + tokens_per_thread; ++i) {
    99→    int32_t expert_id = topk_ids[i];
   100→    /** The cumsum[expert_id] stores the starting index of the tokens that the
   101→     * expert with expert_id needs to process, and
   102→     * tokens_cnts[threadIdx.x][expert_id] stores the indices of the tokens
   103→     * processed by the expert with expert_id within the current thread's token
   104→     * shard.
   105→     */
   106→    int32_t rank_post_pad =
   107→        tokens_cnts[index(num_experts, threadIdx.x, expert_id)] +
   108→        cumsum[expert_id];
   109→    sorted_token_ids[rank_post_pad] = i;
   110→    ++tokens_cnts[index(num_experts, threadIdx.x, expert_id)];
   111→  }
   112→}
