   118→template <typename scalar_t>
   119→__global__ void moe_align_block_size_global_mem_kernel(
   120→    scalar_t* __restrict__ topk_ids, int32_t* sorted_token_ids,
   121→    int32_t* expert_ids, int32_t* total_tokens_post_pad, int32_t num_experts,
   122→    int32_t block_size, size_t numel, int32_t* tokens_cnts, int32_t* cumsum) {
   123→  const size_t tokens_per_thread = CEILDIV(numel, blockDim.x);
   124→  const size_t start_idx = threadIdx.x * tokens_per_thread;
   125→
   126→  for (int i = 0; i < num_experts; ++i) {
   127→    tokens_cnts[index(num_experts, threadIdx.x + 1, i)] = 0;
   128→  }
   129→
   130→  /**
   131→   * In the first step we compute token_cnts[thread_index + 1][expert_index],
   132→   * which counts how many tokens in the token shard of thread_index are
   133→   * assigned to expert expert_index.
   134→   */
   135→  for (int i = start_idx; i < numel && i < start_idx + tokens_per_thread; ++i) {
   136→    ++tokens_cnts[index(num_experts, threadIdx.x + 1, topk_ids[i])];
   137→  }
   138→
   139→  __syncthreads();
   140→
   141→  // For each expert we accumulate the token counts from the different threads.
   142→  if (threadIdx.x < num_experts) {
   143→    tokens_cnts[index(num_experts, 0, threadIdx.x)] = 0;
   144→    for (int i = 1; i <= blockDim.x; ++i) {
   145→      tokens_cnts[index(num_experts, i, threadIdx.x)] +=
   146→          tokens_cnts[index(num_experts, i - 1, threadIdx.x)];
   147→    }
   148→  }
   149→
   150→  __syncthreads();
   151→
   152→  // We accumulate the token counts of all experts in thread 0.
   153→  if (threadIdx.x == 0) {
   154→    cumsum[0] = 0;
   155→    for (int i = 1; i <= num_experts; ++i) {
   156→      cumsum[i] = cumsum[i - 1] +
   157→                  CEILDIV(tokens_cnts[index(num_experts, blockDim.x, i - 1)],
   158→                          block_size) *
   159→                      block_size;
   160→    }
   161→    *total_tokens_post_pad = cumsum[num_experts];
   162→  }
   163→
   164→  __syncthreads();
   165→
   166→  /**
   167→   * For each expert, each thread processes the tokens of the corresponding
   168→   * blocks and stores the corresponding expert_id for each block.
   169→   */
   170→  if (threadIdx.x < num_experts) {
   171→    for (int i = cumsum[threadIdx.x]; i < cumsum[threadIdx.x + 1];
   172→         i += block_size) {
   173→      expert_ids[i / block_size] = threadIdx.x;
   174→    }
   175→  }
   176→
   177→  /**
   178→   * Each thread processes a token shard, calculating the index of each token
   179→   * after sorting by expert number. Given the example topk_ids =
   180→   * [0,1,2,1,2,3,0,3,4] and block_size = 4, then the output would be [0, 6, *,
   181→   * *, 1, 3, *, *, 2, 4, *, *, 5, 7, *, *, 8, *, *, *], where * represents a
   182→   * padding value(preset in python).
   183→   */
   184→  for (int i = start_idx; i < numel && i < start_idx + tokens_per_thread; ++i) {
   185→    int32_t expert_id = topk_ids[i];
   186→    /** The cumsum[expert_id] stores the starting index of the tokens that the
   187→     * expert with expert_id needs to process, and
   188→     * tokens_cnts[threadIdx.x][expert_id] stores the indices of the tokens
   189→     * processed by the expert with expert_id within the current thread's token
   190→     * shard.
   191→     */
   192→    int32_t rank_post_pad =
   193→        tokens_cnts[index(num_experts, threadIdx.x, expert_id)] +
   194→        cumsum[expert_id];
   195→    sorted_token_ids[rank_post_pad] = i;
   196→    ++tokens_cnts[index(num_experts, threadIdx.x, expert_id)];
   197→  }
   198→}
