   200→// taken from
   201→// https://github.com/sgl-project/sglang/commit/cdae77b03dfc6fec3863630550b45bbfc789f957
   202→template <typename scalar_t>
   203→__global__ void sgl_moe_align_block_size_kernel(
   204→    scalar_t* __restrict__ topk_ids, int32_t* sorted_token_ids,
   205→    int32_t* expert_ids, int32_t* total_tokens_post_pad, int32_t num_experts,
   206→    int32_t block_size, size_t numel, int32_t* cumsum) {
   207→  __shared__ int32_t shared_counts[32][8];
   208→
   209→  const int warp_id = threadIdx.x / 32;
   210→  const int experts_per_warp = 8;
   211→  const int my_expert_start = warp_id * experts_per_warp;
   212→
   213→  // Initialize shared_counts for this warp's experts
   214→  for (int i = 0; i < experts_per_warp; ++i) {
   215→    if (my_expert_start + i < num_experts) {
   216→      shared_counts[warp_id][i] = 0;
   217→    }
   218→  }
   219→
   220→  __syncthreads();
   221→
   222→  const size_t tokens_per_thread = CEILDIV(numel, blockDim.x);
   223→  const size_t start_idx = threadIdx.x * tokens_per_thread;
   224→
   225→  for (int i = start_idx; i < numel && i < start_idx + tokens_per_thread; ++i) {
   226→    int expert_id = topk_ids[i];
   227→    int warp_idx = expert_id / experts_per_warp;
   228→    int expert_offset = expert_id % experts_per_warp;
   229→    atomicAdd(&shared_counts[warp_idx][expert_offset], 1);
   230→  }
   231→
   232→  __syncthreads();
   233→
   234→  // Single thread computes cumulative sum and total tokens
   235→  if (threadIdx.x == 0) {
   236→    cumsum[0] = 0;
   237→    for (int i = 1; i <= num_experts; ++i) {
   238→      int expert_count = 0;
   239→      int warp_idx = (i - 1) / experts_per_warp;
   240→      int expert_offset = (i - 1) % experts_per_warp;
   241→      expert_count = shared_counts[warp_idx][expert_offset];
   242→
   243→      cumsum[i] =
   244→          cumsum[i - 1] + CEILDIV(expert_count, block_size) * block_size;
   245→    }
   246→    *total_tokens_post_pad = cumsum[num_experts];
   247→  }
   248→
   249→  __syncthreads();
   250→
   251→  // Assign expert IDs to blocks
   252→  if (threadIdx.x < num_experts) {
   253→    for (int i = cumsum[threadIdx.x]; i < cumsum[threadIdx.x + 1];
   254→         i += block_size) {
   255→      expert_ids[i / block_size] = threadIdx.x;
   256→    }
   257→  }
   258→}
