   277→template <typename scalar_t, int TOPK>
   278→__global__ void moe_sum_kernel(
   279→    scalar_t* __restrict__ out,          // [..., d]
   280→    const scalar_t* __restrict__ input,  // [..., topk, d]
   281→    const int d) {
   282→  const int64_t token_idx = blockIdx.x;
   283→  for (int64_t idx = threadIdx.x; idx < d; idx += blockDim.x) {
   284→    scalar_t x = 0.0;
   285→#pragma unroll
   286→    for (int k = 0; k < TOPK; ++k) {
   287→      x += VLLM_LDG(&input[token_idx * TOPK * d + k * d + idx]);
   288→    }
   289→    out[token_idx * d + idx] = x;
   290→  }
   291→}
