   296→void moe_align_block_size(torch::Tensor topk_ids, int64_t num_experts,
   297→                          int64_t block_size, torch::Tensor sorted_token_ids,
   298→                          torch::Tensor experts_ids,
   299→                          torch::Tensor num_tokens_post_pad) {
   300→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   301→
   302→  int device_max_shared_mem;
   303→  auto dev = topk_ids.get_device();
   304→  cudaDeviceGetAttribute(&device_max_shared_mem,
   305→                         cudaDevAttrMaxSharedMemoryPerBlockOptin, dev);
   306→
   307→  const int32_t num_thread = max((int32_t)num_experts, WARP_SIZE);
   308→  const int32_t shared_mem_i32 =
   309→      ((num_thread + 1) * num_experts + (num_experts + 1)) * sizeof(int32_t);
   310→  const int32_t shared_mem_i16 =
   311→      ((num_thread + 1) * num_experts) * sizeof(uint16_t) +
   312→      (num_experts + 1) * sizeof(int32_t);
   313→
   314→  bool use_global_memory = false;
   315→  bool use_i16 = false;  // Use uint16_t for shared memory token counts
   316→  if (shared_mem_i32 < device_max_shared_mem) {
   317→    // Do nothing in this case. We're all set to use int32_t token counts
   318→  } else if (shared_mem_i16 < device_max_shared_mem &&
   319→             topk_ids.numel() <= 65535) {
   320→    // when nelements of topk_ids is smaller than 65535 (max value of uint16),
   321→    // element value of token_cnts would also smaller than 65535,
   322→    // so we can use uint16 as dtype of token_cnts
   323→    use_i16 = true;
   324→  } else {
   325→    use_global_memory = true;
   326→  }
   327→
   328→  if (use_global_memory) {
   329→    VLLM_DISPATCH_INTEGRAL_TYPES(
   330→        topk_ids.scalar_type(), "moe_align_block_size_global_mem_kernel", [&] {
   331→          // calc needed amount of shared mem for `tokens_cnts` and `cumsum`
   332→          // tensors
   333→          const int32_t num_thread = max((int32_t)num_experts, WARP_SIZE);
   334→
   335→          auto options_int = torch::TensorOptions()
   336→                                 .dtype(torch::kInt)
   337→                                 .device(topk_ids.device());
   338→          torch::Tensor token_cnts_buffer =
   339→              torch::empty({(num_experts + 1) * num_experts}, options_int);
   340→          torch::Tensor cumsum_buffer =
   341→              torch::empty({num_experts + 1}, options_int);
   342→
   343→          auto kernel =
   344→              vllm::moe::moe_align_block_size_global_mem_kernel<scalar_t>;
   345→          kernel<<<1, num_thread, 0, stream>>>(
   346→              topk_ids.data_ptr<scalar_t>(),
   347→              sorted_token_ids.data_ptr<int32_t>(),
   348→              experts_ids.data_ptr<int32_t>(),
   349→              num_tokens_post_pad.data_ptr<int32_t>(), num_experts, block_size,
   350→              topk_ids.numel(), token_cnts_buffer.data_ptr<int32_t>(),
   351→              cumsum_buffer.data_ptr<int32_t>());
   352→        });
   353→  } else if (use_i16) {
   354→    VLLM_DISPATCH_INTEGRAL_TYPES(
   355→        topk_ids.scalar_type(), "moe_align_block_size_kernel", [&] {
   356→          // set dynamic shared mem
   357→          auto kernel =
   358→              vllm::moe::moe_align_block_size_kernel<scalar_t, uint16_t>;
   359→          AT_CUDA_CHECK(VLLM_DevFuncAttribute_SET_MaxDynamicSharedMemorySize(
   360→              (void*)kernel, shared_mem_i16));
   361→          kernel<<<1, num_thread, shared_mem_i16, stream>>>(
   362→              topk_ids.data_ptr<scalar_t>(),
   363→              sorted_token_ids.data_ptr<int32_t>(),
   364→              experts_ids.data_ptr<int32_t>(),
   365→              num_tokens_post_pad.data_ptr<int32_t>(), num_experts, block_size,
   366→              topk_ids.numel());
   367→        });
   368→  } else {
   369→    VLLM_DISPATCH_INTEGRAL_TYPES(
   370→        topk_ids.scalar_type(), "moe_align_block_size_kernel", [&] {
   371→          auto kernel =
   372→              vllm::moe::moe_align_block_size_kernel<scalar_t, int32_t>;
   373→          AT_CUDA_CHECK(VLLM_DevFuncAttribute_SET_MaxDynamicSharedMemorySize(
   374→              (void*)kernel, shared_mem_i32));
   375→          kernel<<<1, num_thread, shared_mem_i32, stream>>>(
   376→              topk_ids.data_ptr<scalar_t>(),
   377→              sorted_token_ids.data_ptr<int32_t>(),
   378→              experts_ids.data_ptr<int32_t>(),
   379→              num_tokens_post_pad.data_ptr<int32_t>(), num_experts, block_size,
   380→              topk_ids.numel());
   381→        });
   382→  }
   383→}
   384→
   385→void sgl_moe_align_block_size(torch::Tensor topk_ids, int64_t num_experts,
   386→                              int64_t block_size,
   387→                              torch::Tensor sorted_token_ids,
   388→                              torch::Tensor experts_ids,
   389→                              torch::Tensor num_tokens_post_pad) {
   390→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   391→  TORCH_CHECK(num_experts == 256,
   392→              "sgl_moe_align_block_size kernel only supports deepseek v3.");
   393→
   394→  VLLM_DISPATCH_INTEGRAL_TYPES(
   395→      topk_ids.scalar_type(), "sgl_moe_align_block_size_kernel", [&] {
   396→        // calc needed amount of shared mem for `cumsum` tensors
   397→        auto options_int =
   398→            torch::TensorOptions().dtype(torch::kInt).device(topk_ids.device());
   399→        torch::Tensor cumsum_buffer =
   400→            torch::zeros({num_experts + 1}, options_int);
   401→
   402→        auto align_kernel =
   403→            vllm::moe::sgl_moe_align_block_size_kernel<scalar_t>;
   404→        align_kernel<<<1, 1024, 0, stream>>>(
   405→            topk_ids.data_ptr<scalar_t>(), sorted_token_ids.data_ptr<int32_t>(),
   406→            experts_ids.data_ptr<int32_t>(),
   407→            num_tokens_post_pad.data_ptr<int32_t>(), num_experts, block_size,
   408→            topk_ids.numel(), cumsum_buffer.data_ptr<int32_t>());
   409→
   410→        const int block_threads = 256;
   411→        const int num_blocks =
   412→            (topk_ids.numel() + block_threads - 1) / block_threads;
   413→        const int max_blocks = 65535;
   414→        const int actual_blocks = std::min(num_blocks, max_blocks);
   415→        auto sort_kernel = vllm::moe::sgl_moe_token_sort_kernel<scalar_t>;
   416→        sort_kernel<<<actual_blocks, block_threads, 0, stream>>>(
   417→            topk_ids.data_ptr<scalar_t>(), sorted_token_ids.data_ptr<int32_t>(),
   418→            cumsum_buffer.data_ptr<int32_t>(), topk_ids.numel());
   419→      });
   420→}
