   422→void moe_sum(torch::Tensor& input,   // [num_tokens, topk, hidden_size]
   423→             torch::Tensor& output)  // [num_tokens, hidden_size]
   424→{
   425→  const int hidden_size = input.size(-1);
   426→  const int num_tokens = output.numel() / hidden_size;
   427→  const int topk = input.size(1);
   428→
   429→  dim3 grid(num_tokens);
   430→  dim3 block(std::min(hidden_size, 1024));
   431→  const at::cuda::OptionalCUDAGuard device_guard(device_of(output));
   432→  const cudaStream_t stream = at::cuda::getCurrentCUDAStream();
   433→
   434→  switch (topk) {
   435→    case 2:
   436→      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
   437→        vllm::moe::moe_sum_kernel<scalar_t, 2><<<grid, block, 0, stream>>>(
   438→            output.data_ptr<scalar_t>(), input.data_ptr<scalar_t>(),
   439→            hidden_size);
   440→      });
   441→      break;
   442→
   443→    case 3:
   444→      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
   445→        vllm::moe::moe_sum_kernel<scalar_t, 3><<<grid, block, 0, stream>>>(
   446→            output.data_ptr<scalar_t>(), input.data_ptr<scalar_t>(),
   447→            hidden_size);
   448→      });
   449→      break;
   450→
   451→    case 4:
   452→      VLLM_DISPATCH_FLOATING_TYPES(input.scalar_type(), "moe_sum_kernel", [&] {
   453→        vllm::moe::moe_sum_kernel<scalar_t, 4><<<grid, block, 0, stream>>>(
   454→            output.data_ptr<scalar_t>(), input.data_ptr<scalar_t>(),
   455→            hidden_size);
   456→      });
   457→      break;
   458→
   459→    default:
   460→      at::sum_out(output, input, 1);
